package ro.leo.visual;
import android.app.*;import android.content.*;import android.media.*;import android.os.*;import java.util.*;
/** Verifies actual audio levels and restores levels, ringer, DND and preferences. */
public final class ProfileTests extends Instrumentation {
    public void onCreate(Bundle b){start();}
    public void onStart(){Context c=getTargetContext();AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);NotificationManager notifications=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);int[] streams={AudioManager.STREAM_MUSIC,AudioManager.STREAM_RING,AudioManager.STREAM_ALARM},levels=new int[3];for(int i=0;i<3;i++)levels[i]=audio.getStreamVolume(streams[i]);int mode=audio.getRingerMode(),filter=notifications.getCurrentInterruptionFilter();SharedPreferences prefs=c.getSharedPreferences("sound-profile",0);Map<String,?> before=prefs.getAll();Bundle result=new Bundle();try{
        if(!notifications.isNotificationPolicyAccessGranted())throw new AssertionError("DND access required for profile test");SoundProfiles.apply(c,5);audio.setStreamVolume(AudioManager.STREAM_MUSIC,levels[0]==0?1:0,0);SoundProfiles.apply(c,4);for(int i=0;i<3;i++)if(audio.getStreamVolume(streams[i])!=levels[i])throw new AssertionError("custom profile restores stream "+i);
        SoundProfiles.apply(c,3);for(int attempt=0;attempt<40&&notifications.getCurrentInterruptionFilter()!=NotificationManager.INTERRUPTION_FILTER_ALARMS;attempt++)SystemClock.sleep(50);if(notifications.getCurrentInterruptionFilter()!=NotificationManager.INTERRUPTION_FILTER_ALARMS)throw new AssertionError("night DND allows alarms");if(audio.getRingerMode()!=AudioManager.RINGER_MODE_SILENT||audio.getStreamVolume(AudioManager.STREAM_MUSIC)!=0||audio.getStreamVolume(AudioManager.STREAM_ALARM)!=levels[2])throw new AssertionError("night silences music/ringer and preserves alarm");SoundProfiles.apply(c,2);if(audio.getRingerMode()!=AudioManager.RINGER_MODE_NORMAL||audio.getStreamVolume(AudioManager.STREAM_RING)!=audio.getStreamMaxVolume(AudioManager.STREAM_RING))throw new AssertionError("outdoor uses full ring volume");result.putString("result","PASS save/custom restore, night alarm preservation, outdoor ringer");
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{try{for(int i=0;i<3;i++)audio.setStreamVolume(streams[i],levels[i],0);audio.setRingerMode(mode);notifications.setInterruptionFilter(filter);SharedPreferences.Editor editor=prefs.edit().clear();for(Map.Entry<String,?> item:before.entrySet()){Object v=item.getValue();if(v instanceof String)editor.putString(item.getKey(),(String)v);else if(v instanceof Integer)editor.putInt(item.getKey(),(Integer)v);else if(v instanceof Boolean)editor.putBoolean(item.getKey(),(Boolean)v);}editor.commit();}catch(RuntimeException e){result.putString("restore_error",e.toString());}}
        finish(result.containsKey("error")||result.containsKey("restore_error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);
    }
}
